#!/usr/bin/env bash
# Mutation proof for honey-initd-lint (generated by agents-bots-honey.org): each sabotaged copy of the lint MUST fail test_initd_lint.py by a NAMED
# unittest failure. A pass, a timeout or an infrastructure error is never a kill. Pure Python, no root, no OpenRC; the real lint is not modified.
# Exit 0 = every mutant killed, 1 = a survivor or an error.
set -uo pipefail
HERE="$(CDPATH= cd -- "$(dirname -- "$0")" && pwd -P)"
LINT="${HONEY_INITD_LINT:-}"
[ -n "$LINT" ] || for c in "$HERE/../../../bin/honey-initd-lint" "$HERE/honey-initd-lint"; do [ -f "$c" ] && { LINT="$c"; break; }; done
[ -f "$LINT" ] || { echo "mutation-check-initd-lint: lint not found"; exit 1; }
TMP="$(mktemp -d)"; trap 'rm -rf "$TMP"' EXIT
fail=0; killed=0
mutate() { # name sed-expression
  local name="$1" expr="$2" d="$TMP/$1" out rc names
  mkdir -p "$d"; cp "$LINT" "$d/honey-initd-lint"; sed -i "$expr" "$d/honey-initd-lint"
  if cmp -s "$LINT" "$d/honey-initd-lint"; then echo "MUTATION NOT APPLIED: $name"; fail=1; return; fi
  out="$(HONEY_INITD_LINT="$d/honey-initd-lint" timeout 300 python3 "$HERE/test_initd_lint.py" 2>&1)"; rc=$?
  if [ "$rc" = 124 ]; then echo "TIMEOUT (infrastructure, NOT a kill): $name"; fail=1; return; fi
  if ! printf '%s\n' "$out" | grep -qE '^(FAILED \(|OK)'; then echo "INFRASTRUCTURE ERROR (not a kill): $name"; printf '%s\n' "$out" | tail -5 | sed 's/^/    | /'; fail=1; return; fi
  names="$(printf '%s\n' "$out" | grep -E '^(FAIL|ERROR):' | sed 's/^[A-Z]*: //; s/ (.*//' | head -3 | tr '\n' ' ')"
  if [ -n "$names" ]; then killed=$((killed+1)); echo "killed: $name by: $names"
  else echo "SURVIVED (tests too weak): $name"; fail=1; fi
}
mutate no-own-stop-rule-off        "s/^        if daemon_shared:\$/        if False:/"
mutate stop-exec-rule-off          "s/elif shared_reason(ev):/elif False:/"
mutate stop-exec-unresolved-off    "s/if ev is None and daemon_shared:/if False:/"
mutate unscoped-pattern-ok         "s/elif not uid:/elif False:/"
mutate bare-interpreter-ok         "s/bare = bool(pv and pv.split() and is_shared(pv.split()\[0\]))/bare = False/"
mutate shared-daemon-pattern-ok    "s/if daemon_shared or bare:/if bare:/"
mutate ssd-name-rule-off           "s/if (nv is None and daemon_shared) or (nv is not None and shared_reason(nv)):/if False:/"
mutate uid-scoped-becomes-fault    "s/notes.append((n, '%s: pattern %r, uid-scoped' % (cmd, pv)))/faults.append((n, 'stop-by-name', 'x'))/"
mutate unparsed-fails-the-run      "s/rc = 1 if s\['fault'\] else 0/rc = 1 if (s['fault'] or s['unparsed']) else 0/"
mutate inactive-copies-count       "s/act = \[r for r in rows if not r\['inactive'\]\]/act = rows/"
mutate comments-not-stripped       "s/if c == '#' and (k == 0 or cur\[k - 1\] in ' \\\\t;&|('):/if False:/"
mutate heredoc-not-skipped         "s/m = HEREDOC_RE.search(line)/m = None/"
mutate confd-ignored               "s/if confd and os.path.isfile(os.path.join(confd, name)):/if False:/"
mutate default-expansion-broken    "s/if op in (':-', '-', ':=', '='):/if False:/"
mutate sysv-pidfile-narrowing-off  "s/narrowed = kind == 'sysv' and pid is not None/narrowed = False/"
mutate perl-not-shared             "s/perl\[0-9.\]\*|//"
mutate node-not-shared             "s/node(js)?|//"
mutate dotfiles-scanned            "s/ or os.path.basename(p).startswith('.')//"
mutate stop-post-not-examined      "s/^STOP_FUNCS = .*/STOP_FUNCS = ('stop',)/"
mutate stop-pre-not-examined       "s/^STOP_FUNCS = .*/STOP_FUNCS = ('stop', 'stop_post')/"
mutate lint-bug-becomes-ok         "s/return dict(base, why='lint error: %s: %s' % (type(e).__name__, e))/return dict(base, status='OK')/"
mutate unreadable-dir-is-ok        "s/            return 2\$/            return 0/"
mutate computed-command-is-na      "s/if not cmd_known and cmd_line:/if False:/"
mutate tail-hint-removed           "s/if len(tail) == 2 and tail\[1\] and '\$' not in tail\[1\]:/if False:/"
mutate supervise-shared-is-fault   "s/return dict(res, status='UNPARSED', line=0, why='supervisor=%s on a shared-interpreter daemon: its stop semantics are not modelled' % sup)/res['faults'].append((0, 'no-own-stop', 'x'))/"
mutate sh-c-not-followed           "s/if depth < 3 and os.path.basename(words\[0\]) in ('su', 'sh', 'bash', 'dash') and '-c' in words\[:-1\]:/if False:/"
mutate substitutions-not-followed  "s/    for s in inner:\$/    for s in []:/"
mutate pgrep-needs-no-kill         "s/or (cmd == 'pgrep' and kills):/or cmd == 'pgrep':/"
mutate redirections-kept           "s/        words = strip_redirections(words)/        pass/"
WATCHSRC="${HONEY_INITD_LINT_WATCH:-}"
[ -n "$WATCHSRC" ] || for c in "$HERE/../../../bin/honey-initd-lint-watch" "$HERE/honey-initd-lint-watch"; do [ -f "$c" ] && { WATCHSRC="$c"; break; }; done
mutate_watch() { # name sed-expression  (mutates the watcher, not the lint)
  local name="$1" expr="$2" d="$TMP/w-$1" out names
  mkdir -p "$d"; cp "$WATCHSRC" "$d/honey-initd-lint-watch"; sed -i "$expr" "$d/honey-initd-lint-watch"
  if cmp -s "$WATCHSRC" "$d/honey-initd-lint-watch"; then echo "MUTATION NOT APPLIED: $name"; fail=1; return; fi
  out="$(HONEY_INITD_LINT_WATCH="$d/honey-initd-lint-watch" HONEY_INITD_LINT="$LINT" timeout 300 python3 "$HERE/test_initd_lint.py" 2>&1)"
  if ! printf '%s\n' "$out" | grep -qE '^(FAILED \(|OK)'; then echo "INFRASTRUCTURE ERROR (not a kill): $name"; fail=1; return; fi
  names="$(printf '%s\n' "$out" | grep -E '^(FAIL|ERROR):' | sed 's/^[A-Z]*: //; s/ (.*//' | head -3 | tr '\n' ' ')"
  if [ -n "$names" ]; then killed=$((killed+1)); echo "killed: $name [watcher] by: $names"; else echo "SURVIVED (tests too weak): $name [watcher]"; fail=1; fi
}
if [ -n "$WATCHSRC" ]; then
mutate_watch ignores-conf-d            "s|find \"\$DIR\" \"\$CONFD\" -maxdepth|find \"\$DIR\" -maxdepth|"
mutate_watch hashes-names-not-content  "s/xargs -0 -r sha256sum/xargs -0 -r ls -l/"
mutate_watch no-daily-rerun            "s/-lt \"\$MAX_AGE\" \]/-ge 0 ]/"
mutate_watch alert-on-every-run        "s/\[ \"\${faulting:-none}\" != \"\${prev_faulting:-none}\" \]/true/"
mutate_watch lint-change-not-seen      "s/; sha256sum \"\$LINT\"//"
mutate_watch force-ignored             "s/\[ \"\$FORCE\" = 0 \] \&\& //"
mutate_watch missing-lint-not-checked  "s/^\[ -f \"\$LINT\" \] || .*\$/:/"
fi
echo "mutants: $killed killed"
[ "$fail" = 0 ] || exit 1
exit 0
